import { emptySpace, restoreSpace, getPath, choosePath, markStep, saveGuide, readingListText } from './paths.js';
import { continueHome, pathsPage, pathPage, mySpace, pathReturn } from './guided-ui.js';
import { artImage, artPanel, GUIDE_ART, TOOL_ART } from './art.js';
import {ARTICLES,CATEGORIES,PROMPTS,COACH_FAQ} from './data.js';
import {QUESTIONS,DIMENSIONS,assess,DYNAMIC_QUESTIONS,SCALE,scoreDynamics} from './engine.js';
import { getActivity } from './activities.js';
import { renderActivity, attachActivityHandlers } from './activity-ui.js';
import { answerQuestion, GUIDANCE_CHOICES } from './ask-guidance.js';
const $=s=>document.querySelector(s);
const main=$('#main');
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(kind='spark')=>{const paths={spark:'M24 3v42M3 24h42M9 9l30 30M9 39 39 9',heart:'M24 40S4 28 4 15C4 3 20 1 24 13 28 1 44 3 44 15c0 13-20 25-20 25Z',leaf:'M8 39C6 15 22 6 41 7c1 20-9 32-29 29M10 37 32 16',chat:'M7 7h34v27H23L12 42v-8H7V7Zm9 10h16m-16 8h10',lock:'M14 21v-7a10 10 0 0 1 20 0v7M10 21h28v21H10V21Z'};return `<svg viewBox="0 0 48 48" fill="none" stroke="currentColor" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[kind]||paths.spark}"/></svg>`;};
const blankFlow=()=>({active:false,answers:{},step:0,completed:false});
const state={space:emptySpace(),savedOnly:false,journey:blankFlow(),dynamics:blankFlow(),filter:'All topics',search:'',cards:{level:'gentle',index:0},notes:{},checkin:{},boundary:{},care:{},coach:{},activityAnswers:{}};
let sessionStorageAvailable=true;
let adult=false;
try{adult=sessionStorage.getItem('vi-adult')==='yes';const saved=JSON.parse(sessionStorage.getItem('vi-session')||'null');if(saved&&typeof saved==='object'){state.space=restoreSpace(saved.space);for(const key of ['journey','dynamics']){const f=saved[key];if(f&&typeof f==='object')state[key]={active:!!f.active,answers:f.answers&&typeof f.answers==='object'?f.answers:{},step:Math.max(0,Math.min(Number.isInteger(f.step)?f.step:0,key==='journey'?QUESTIONS.length-1:DYNAMIC_QUESTIONS.length-1)),completed:!!f.completed};}for(const key of ['notes','checkin','boundary','care','coach'])if(saved[key]&&typeof saved[key]==='object')state[key]=saved[key];const a=saved.activityAnswers;if(a&&typeof a==='object'&&!Array.isArray(a)){for(const [key,value] of Object.entries(a)){if(['goal','tone','note','_generated'].includes(key)&&typeof value==='string')state.activityAnswers[key]=value.slice(0,key==='note'?1000:4000);}}}}catch{}
function persist(){try{const{space,journey,dynamics,notes,checkin,boundary,care,coach,activityAnswers}=state;sessionStorage.setItem('vi-session',JSON.stringify({space,journey,dynamics,notes,checkin,boundary,care,coach,activityAnswers}));sessionStorageAvailable=true;}catch{sessionStorageAvailable=false;}}
function toast(message){const t=$('#toast');t.textContent=message;t.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>{t.hidden=true;},4200);}
function download(name,text,type='text/plain;charset=utf-8'){const a=document.createElement('a');const u=URL.createObjectURL(new Blob([text],{type}));a.href=u;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),2000);}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('Copied. Share only where you feel comfortable.');}catch{download('Vulpes-Ignis-note.txt',text);toast('A text copy was downloaded.');}}
function title(name){document.title=name?`${name} · Vulpes Ignis`:'Vulpes Ignis · A little curiosity. A deeper connection.';}
function saveButton(id){const saved=state.space.saved.includes(id),a=ARTICLES.find(guide=>guide.id===id);return `<button class="save-guide" data-action="toggle-save" data-guide="${id}" aria-pressed="${saved}" aria-label="${saved?'Unsave':'Save'} guide: ${escape(a.title)}"><span aria-hidden="true">${saved?'✓':'+'}</span> ${saved?'Saved guide':'Save guide'}</button>`;}
function card(a){const count=a.body.replace(/<[^>]+>/g,' ').split(/\s+/).length;return `<article class="guide-card"><a class="article-card" href="#/learn/${a.id}"><div class="article-art has-site-art ${a.art}" aria-hidden="true">${artImage(GUIDE_ART[a.id],{card:true})}</div><div class="article-meta"><span class="category">${a.category}</span><span>·</span><span>${Math.max(2,Math.ceil(count/180))} MIN READ</span></div><h3>${a.title}</h3><p>${a.excerpt}</p><span class="read-link">Read the guide</span></a><div class="guide-card-actions">${saveButton(a.id)}</div></article>`;}
function pageHead(eyebrow,heading,lead,art){const copy=`<div class="page-hero"><p class="eyebrow">${eyebrow}</p><h1>${heading}</h1><p class="lead">${lead}</p></div>`;return art?`<div class="illustrated-head">${copy}${artPanel(art)}</div>`:copy;}
function home(){title();return `<div class="wrap">${continueHome(state.space)}<section class="hero" aria-labelledby="hero-title"><div class="hero-copy"><p class="eyebrow">FOR CURIOUS ADULTS. FOR REAL CONNECTION.</p><h1 id="hero-title">Learn what moves you.<br><em>Connect on your terms.</em></h1><p class="lead">Clear, pressure-free education about intimacy, relationships, and sexual wellness. Explore your questions, practice conversations, and decide what feels right for you.</p><div class="button-row hero-actions"><a href="#/paths" class="button primary">Help me get started</a><a href="#/tools" class="button secondary">Try a free tool</a></div><p class="hero-browse"><a class="text-link" href="#/learn">Or browse the guides</a></p><p class="fine">${icon('lock')} No account required. Private reflections stay in this tab.</p></div><div class="hero-art">${artImage('foxfire-fox',{hero:true})}<span class="art-caption">A LITTLE CURIOSITY GOES A LONG WAY</span></div></section><div class="values-strip"><span><b aria-hidden="true">✳</b> For every kind of grown-up</span><span><b aria-hidden="true"></b> Curiosity without pressure</span><span><b aria-hidden="true">♡</b> Connection over perfection</span><span><b aria-hidden="true">◈</b> Privacy by design</span></div><section class="section quick-tools" aria-labelledby="quick-tools-title"><div class="section-heading"><div><p class="eyebrow">SOMETHING USEFUL, RIGHT NOW</p><h2 id="quick-tools-title">Start with one small thing.</h2></div><p class="section-subtitle">No quiz or signup required. These free tools help you put a thought into words, privately and at your own pace.</p></div><div class="quick-tools-grid"><a class="quick-tool" href="#/tools/conversation"><span class="quick-tool-icon">${icon('chat')}</span><span class="quick-tool-copy"><strong>Start a conversation</strong><span>Find a question worth asking, together or on your own.</span><span class="quick-tool-cta">Open conversation cards</span></span></a><a class="quick-tool" href="#/tools/check-in"><span class="quick-tool-icon">${icon('heart')}</span><span class="quick-tool-copy"><strong>Make a gentle check-in</strong><span>Notice what you need and what has felt good lately.</span><span class="quick-tool-cta">Build a check-in</span></span></a><a class="quick-tool" href="#/tools/boundaries"><span class="quick-tool-icon">${icon('leaf')}</span><span class="quick-tool-copy"><strong>Find words for a boundary</strong><span>Practice saying what works for you, without pressure.</span><span class="quick-tool-cta">Explore boundary wording</span></span></a></div></section><section class="section"><div class="section-heading"><div><p class="eyebrow">THERE’S NO RIGHT PLACE TO START</p><h2>What’s on your mind?</h2></div><p class="section-subtitle">A question. A quiet wish. A “what if.”<br>There’s room for all of it here.</p></div><div class="path-grid"><a class="path-card" href="#/paths/confidence"><div class="path-icon">${icon('leaf')}</div><h3>Understand yourself</h3><p>A short guide, a little reflection, and words for what you need.</p><span class="corner-arrow" aria-hidden="true"></span></a><a class="path-card" href="#/paths/connection"><div class="path-icon">${icon('heart')}</div><h3>Feel a little closer</h3><p>Make room for a willing conversation, one small check-in at a time.</p><span class="corner-arrow" aria-hidden="true"></span></a><a class="path-card" href="#/paths/curiosity"><div class="path-icon">${icon('spark')}</div><h3>Follow your curiosity</h3><p>Explore preferences and possibilities. No labels required. No rush, either.</p><span class="corner-arrow" aria-hidden="true"></span></a></div><a class="text-link all-paths-link" href="#/paths">See all five guided paths</a></section><section class="feature" aria-labelledby="feature-title"><div class="feature-copy"><p class="eyebrow">A SMALL STEP INWARD</p><h2 id="feature-title">Not sure where to begin?<br>Let’s find your spark.</h2><p>A few gentle questions. A few thoughtful starting points. Discover the learning paths that meet you where you are.</p><a href="#/assessment" class="button primary">Find my starting point <span aria-hidden="true"></span></a><p class="fine" style="margin:15px 0 0">About 3 minutes · Private · Skip any question</p></div>${artPanel('rooted-flame','feature-art')}</section><section class="section"><div class="section-heading"><div><p class="eyebrow">SOMETHING WORTH SITTING WITH</p><h2>A little understanding<br>changes the conversation.</h2></div><a class="text-link" href="#/learn">Explore the library <span aria-hidden="true"></span></a></div><div class="article-grid">${[ARTICLES[0],ARTICLES[2],ARTICLES[3]].map(card).join('')}</div></section><section class="quote-band"><p class="eyebrow">THE HEART OF VULPES IGNIS</p><blockquote>“You don’t have to have it all figured out<br>to deserve understanding.”</blockquote><p>Come with questions. Leave with something useful.</p></section><section class="section"><div class="toolkit-banner">${artPanel('learning-journal','toolkit-art')}<div class="toolkit-copy"><p class="eyebrow">A LITTLE SOMETHING TO TAKE WITH YOU</p><h2>Connection, in practice.</h2><p>Conversation starters, a gentle check-in, and space to reflect. Free tools for the beautifully unfinished work of being human.</p><a href="#/tools" class="text-link">Open the toolkit <span aria-hidden="true"></span></a><p class="fine" style="margin:15px 0 0;color:#536045">Yours to use. No inbox toll required.</p></div></div></section></div>`;}
function library(){title('The learning library');return `<div class="wrap section" style="padding-top:0">${pageHead('A LITTLE UNDERSTANDING','There’s room for<br>your questions.','Clear guidance, practical ideas, and conversations worth having. Follow what feels useful. Leave the rest for another day.','learning-journal')}<div class="search-row"><div class="search-field"><label for="library-search" class="visually-hidden">Search articles</label><input id="library-search" type="search" placeholder="What are you curious about?" value="${escape(state.search)}" autocomplete="off"><span aria-hidden="true">⌕</span></div><span class="fine">Original guides · No personal profile needed</span></div><div class="saved-filter-row"><button class="filter" data-action="saved-only" aria-pressed="${state.savedOnly}">${state.savedOnly?'Showing saved guides':'My saved guides'} · ${state.space.saved.length}</button><a class="text-link" href="#/my-space">Open my space</a></div><div class="filters" aria-label="Filter articles by topic">${CATEGORIES.map(c=>`<button class="filter ${state.filter===c?'active':''}" aria-pressed="${state.filter===c}" data-filter="${escape(c)}">${c}</button>`).join('')}</div><p id="library-count" class="fine" role="status" style="margin-bottom:24px"></p><div class="article-grid library-grid" id="library-results">${filteredArticles()}</div></div>`;}
function matchingArticles(){const search=state.search.toLowerCase().trim();return ARTICLES.filter(a=>(!state.savedOnly||state.space.saved.includes(a.id))&&(state.filter==='All topics'||a.category===state.filter)&&(!search||`${a.title} ${a.excerpt} ${a.category} ${a.body.replace(/<[^>]+>/g,' ')}`.toLowerCase().includes(search)));}
function filteredArticles(){const entries=matchingArticles();return entries.length?entries.map(card).join(''):`<div class="empty"><h3>${state.savedOnly?'No saved guides match this view.':'No guides found for that search.'}</h3><p>${state.savedOnly?'Save a guide to return to it, or show all guides.':'Try a different word, or browse all topics.'}</p><button class="text-link" data-action="reset-search">Show all guides </button></div>`;}
function articlePage(id){const a=ARTICLES.find(a=>a.id===id);if(!a)return notFound();title(a.title);const headings=[...a.body.matchAll(/<h2 id="([^"]+)">([^<]+)<\/h2>/g)];const words=a.body.replace(/<[^>]+>/g," ").trim().split(/\s+/).filter(Boolean).length;const readMinutes=Math.max(2,Math.ceil(words/180));const related=ARTICLES.filter(x=>x.id!==id&&x.category===a.category).slice(0,2);const activity=getActivity(id);return `<div class="wrap"><div class="article-head"><a class="back-link" href="#/learn"> Back to the library</a><div class="article-meta"><span class="category">${a.category}</span><span>·</span><span>Vulpes Ignis original guide</span><span>·</span><span>${readMinutes} MIN READ</span></div><h1>${a.title}</h1><p class="lead">${a.excerpt}</p>${a.editorialFormat?`<p class="fine editorial-format">${escape(a.editorialFormat)}</p>`:""}<section class="article-learning" aria-label="What you will explore"><p class="eyebrow">WHAT YOU WILL EXPLORE</p><ul>${headings.slice(0,3).map(([,headingId,heading])=>`<li>${escape(heading)}</li>`).join("")}</ul></section><div class="article-toolbar">${saveButton(a.id)}<a class="text-link" href="#/my-space">My space</a></div></div>${artPanel(GUIDE_ART[a.id],'guide-illustration')}${headings.length?`<details class="article-contents-mobile"><summary>On this page · ${headings.length} sections</summary><nav aria-label="Article contents">${headings.map(([,headingId,heading])=>`<a href="#${headingId}" data-scroll="${headingId}">${escape(heading)}</a>`).join("")}</nav></details>`:""}<div class="article-layout"><article class="article-body">${a.body}<div class="practice"><p class="eyebrow">ONE SMALL THING TO TRY</p><p>${a.practice}</p>${activity?`<a class="button primary" href="#/activity/${a.id}">Try the conversation activity</a>`:""}<a href="#/tools/${a.tool}" class="text-link" style="margin-top:20px">Try a practical tool <span aria-hidden="true"></span></a></div>${a.sources.length?`<div class="sources"><h3>Read further, from primary sources</h3><p>${a.sourcesCheckedOn?"The numbered links support factual points. Examples and optional exercises are original editorial suggestions. This guide has not been clinically reviewed.":"Health-related points draw on these sources. This guide has not been clinically reviewed."}</p>${a.sources.map(s=>`<a href="${s.url}" target="_blank" rel="noopener noreferrer">${s.name} </a>`).join('')}<p class="fine" style="margin-top:10px">Sources checked ${escape(a.sourcesCheckedOn||"October 28, 2026")}. Guidance can change.</p></div>`:''}<div class="article-review-note"><strong>Editorial status:</strong> ${a.sourcesCheckedOn?"Source-checked educational guide. Examples and prompts are not validated assessments.":"Original educational guide."} No clinical or specialist review is claimed. ${a.sources.length?"Linked sources support selected points; check dates and current guidance.":"No external sources are listed for this guide."} Education, not diagnosis or personalized care.</div><div class="button-row no-print" style="margin-top:25px"><button class="button secondary" data-action="print">Print this guide</button><a href="#/learn" class="button subtle">Keep exploring </a></div>${related.length?`<section class="article-related" aria-label="Related reading"><h2>Keep exploring</h2><ul>${related.map(x=>`<li><a href="#/learn/${x.id}">${escape(x.title)}</a></li>`).join("")}</ul></section>`:""}</article><aside class="article-aside" aria-label="Article contents and other options"><p class="eyebrow">IN THIS GUIDE</p>${headings.map(([_,id,t])=>`<a href="#${id}" data-scroll="${id}">${t}</a>`).join('')}<a href="#/assessment" class="button primary">Find your spark </a><p class="fine" style="margin-top:16px">A personal starting point,<br>without personal data collection.</p></aside></div></div>`;}
function explore(){title('Explore yourself');return `<div class="wrap section" style="padding-top:0">${pageHead('FOLLOW A LITTLE CURIOSITY','Meet yourself<br>where you are.','An invitation to reflect, with space for uncertainty. These tools offer language and learning paths. You decide what fits.','curiosity-garden')}<div class="explore-grid"><section class="explore-card"><span class="large-spark" aria-hidden="true">✳</span><p class="eyebrow">YOUR STARTING POINT</p><h2>Find your spark.</h2><p>A broad, private reflection on confidence, connection, body understanding, and what you want help with. Get three relevant learning paths.</p><a href="#/assessment" class="button primary">Find my spark </a><p class="fine" style="margin-top:16px">11 questions · About 3 minutes · Skippable</p></section><section class="explore-card rose-card"><span class="large-spark" aria-hidden="true">✳</span><p class="eyebrow">A SEPARATE EXPLORATION</p><h2>Curious about<br>your dynamics?</h2><p>Explore language for adult consensual roles, care, playfulness, and power exchange. An original reflection, with room for more than one answer.</p><a href="#/dynamics" class="button secondary">Explore adult dynamics </a><p class="fine" style="margin-top:16px">25 statements · About 5 minutes · 18+ only</p></section></div><div class="notice green-notice">You don’t need a result to belong here. Both tools are optional, unvalidated educational exercises. They do not diagnose, define your identity, or assess compatibility.</div><div class="steps"><div class="step"><span class="number">01 / YOUR CHOICE</span><h3>Skip what you like.</h3><p>You never owe a website an answer. Every assessment question can be skipped.</p></div><div class="step"><span class="number">02 / YOUR PRIVACY</span><h3>Your answers stay here.</h3><p>Answers remain in this tab’s session. They aren’t sent to Vulpes Ignis.</p></div><div class="step"><span class="number">03 / YOUR NEXT STEP</span><h3>Take what is useful.</h3><p>Results link to real guides and tools. A percentage never tells you what you have to do.</p></div></div></div>`;}
function assessmentIntro(type){const dynamics=type==='dynamics';const f=state[type];title(dynamics?'Adult dynamics reflection':'Find your spark');return `<div class="wrap"><section class="intro-panel">${artPanel(dynamics?'interwoven-glass':'rooted-flame','reflection-illustration')}<p class="eyebrow">${dynamics?'ADULT DYNAMICS REFLECTION':'A SMALL STEP INWARD'}</p><h1>${dynamics?'A few words for<br>your curiosity.':'Let’s find<br>your spark.'}</h1><p>${dynamics?'Explore 25 statements about consensual adult roles, care, play, and power exchange. You’ll see how your answers relate to nine role themes, with clear scoring and explanations.':'Answer a few gentle questions about what you’d like to understand. We’ll suggest relevant articles and a practical next step, and explain why each path appeared.'}</p><div class="intro-points"><span>◈ Answers stay in this tab</span><span> ${dynamics?'About 5 minutes':'About 3 minutes'}</span><span>♡ Skip any question</span></div><div class="notice">${dynamics?'This is an original, unvalidated vocabulary exercise for consenting adults. Scores reflect your responses, not an identity diagnosis or permission for any activity. Adult role labels do not remove consent or autonomy.':'This recommends educational resources. It is not a medical assessment, diagnosis, or emergency triage tool. You don’t need to provide names, health records, or contact details.'}</div><p class="fine">Your browser may restore tab sessions. Use “Clear my private session” to remove answers and notes explicitly. Downloaded files stay on your device until you delete them.</p><div class="button-row"><button class="button ${dynamics?'pink-button':'primary'}" data-action="start" data-flow="${type}">${Object.keys(f.answers).length?'Continue my reflection':'Let’s begin'} <span aria-hidden="true"></span></button><a class="button subtle" href="#/learn">I’d rather browse </a></div>${f.completed?`<a href="#/${dynamics?'dynamics-results':'results'}" class="text-link" style="margin-top:20px">See my last result </a>`:''}</section></div>`;}
function quiz(type){const dyn=type==='dynamics';const f=state[type];const qs=dyn?DYNAMIC_QUESTIONS:QUESTIONS;const q=qs[f.step];const options=dyn?SCALE.map(s=>({id:String(s.value),label:s.label})):q.options;const selected=f.answers[q.id];const has=selected!==undefined;title(`${dyn?'Dynamics reflection':'Find your spark'} · ${f.step+1} of ${qs.length}`);return `<section class="quiz-shell"><div class="quiz-top"><a href="#/explore"> Explore yourself</a><span>${f.step+1} of ${qs.length}</span></div><div class="progress" role="progressbar" aria-label="Assessment progress" aria-valuemin="0" aria-valuemax="${qs.length}" aria-valuenow="${f.step}"><span style="width:${f.step/qs.length*100}%"></span></div><p class="eyebrow">${dyn?'A REFLECTION, NOT A LABEL':'YOUR PACE. YOUR PATH.'}</p><h1 class="quiz-question" id="question-title">${dyn?q.text:q.title}</h1><p class="quiz-context">${dyn?'How much does this resonate with you? All statements refer to freely chosen dynamics between consenting adults.':q.note}</p><fieldset class="answers" aria-labelledby="question-title"><legend class="visually-hidden">Choose one answer, or skip this question</legend>${options.map((o,i)=>`<label class="answer ${String(selected)===o.id?'selected':''}"><input class="visually-hidden" type="radio" name="quiz-answer" value="${o.id}" data-flow="${type}" ${String(selected)===o.id?'checked':''}><span>${o.label}</span></label>`).join('')}</fieldset><div class="quiz-actions"><button class="text-link" data-action="back" data-flow="${type}">${f.step?' Previous':' Introduction'}</button><button class="button primary" data-action="next" data-flow="${type}" ${has?'':'disabled'}>${f.step===qs.length-1?'See my reflection':'Continue'} <span aria-hidden="true"></span></button></div><div class="quiz-end"><button class="link-button" data-action="skip" data-flow="${type}">${f.step===qs.length-1?'Skip & see my reflection':'Skip this question'}</button><p class="fine" style="margin-top:17px">Private to this tab. No answers are sent to Vulpes Ignis. <button class="link-button clear-session">Clear my private session</button></p></div></section>`;}
function journeyResults(){title('Your starting points');const f=state.journey;if(!f.completed)return noResults(false);const r=assess(f.answers);const reasons=id=>QUESTIONS.filter(q=>q.options.find(x=>x.id===f.answers[q.id])?.weights[id]>0).map(q=>{const o=q.options.find(x=>x.id===f.answers[q.id]);return o.label+' (+'+o.weights[id]+' points)';});return `<div class="wrap section" style="padding-top:0"><div class="result-header"><p class="eyebrow">A FEW PLACES TO BEGIN</p><h1>${r.answered?'A little closer<br>to your next step.':'You left room<br>for curiosity.'}</h1><p class="lead">${r.answered?'These are learning paths suggested by your answers. They’re invitations to explore, and you can choose a different direction at any time.':'You skipped every question, so there isn’t enough information for a personal recommendation. You can still browse freely.'}</p><p class="fine" style="margin-top:15px">${r.answered} of ${QUESTIONS.length} questions answered · Answers remain in this tab</p></div>${r.comfortNote?`<div class="notice">${r.comfortNote} <a href="#/learn/when-intimacy-hurts">Read about comfort and care </a></div>`:''}${r.paths.length?`<div class="result-grid">${r.paths.map((p,i)=>`<section class="result-card"><span class="result-number">0${i+1}</span><h2>${p.name}</h2><p>${p.reason}</p><a href="#/learn/${p.article}" class="text-link">Start with this guide </a></section>`).join('')}</div>`:`<div class="notice green-notice">Your answers didn’t point strongly to a specific path. <a href="#/learn">Wander the full library </a></div>`}${r.formatTool?`<div class="practice"><p class="eyebrow">IN THE FORMAT YOU CHOSE</p><h2 style="font-size:2rem;margin-bottom:14px">One small thing to try.</h2><p>Because you chose ${escape(QUESTIONS.find(q=>q.id==='format').options.find(o=>o.id===f.answers.format)?.label.toLowerCase()||'a practical next step')}, you might like this tool.</p><a href="#/tools/${r.formatTool}" class="text-link" style="margin-top:18px">Open my practical tool </a></div>`:''}<div class="scores-panel"><h2>Why these paths?</h2><p class="fine">This is a fixed set of rules, not AI. Each answer adds stated points to relevant learning areas. Skipped answers add nothing. Ties use the displayed dimension order. An explicit care signal can reserve a professional-care path.</p><details><summary>See my answer contributions and all nine areas</summary>${Object.entries(DIMENSIONS).map(([id,d])=>`<div style="padding:13px 0;border-bottom:1px solid var(--line)"><strong style="font-size:.86rem;font-weight:400">${d.name} · ${r.scores[id]} points</strong><p class="fine">${reasons(id).length?reasons(id).map(escape).join(' · '):'No answer added points to this area.'}${id==='care'&&!r.careSignal?' Care points are set to zero without an explicit care-related answer.':''}</p></div>`).join('')}<p class="fine" style="margin-top:15px">Points rank learning resources. They do not measure health, risk, severity, or ability.</p></details></div><div class="result-actions no-print"><button class="button primary" data-action="download-result" data-flow="journey">Save my reflection </button><button class="button secondary" data-action="print">Print</button><button class="button secondary" data-action="retake" data-flow="journey">Revisit my answers</button><a class="button subtle" href="#/learn">Browse all guides </a></div><p class="fine">Saved files contain your result and remain on your device. Email results are not sent by this site.</p></div>`;}
function noResults(dyn){return `<div class="wrap section">${pageHead('YOUR OWN PACE','Nothing to rush.','Complete a reflection when you’re ready, or explore the library without one.')}<a class="button primary" href="#/${dyn?'dynamics':'assessment'}">${dyn?'Explore adult dynamics':'Find your spark'} </a></div>`;}
function dynamicsResults(){title('Your dynamics reflection');if(!state.dynamics.completed)return noResults(true);const r=scoreDynamics(state.dynamics.answers);return `<div class="wrap section" style="padding-top:0"><div class="result-header"><p class="eyebrow">WORDS FOR YOUR CURIOSITY</p><h1>${r.signal?'A few themes<br>to sit with.':'No label required.'}</h1><p class="lead">${r.signal?'These themes received the strongest agreement in the statements you answered. You can relate to several, none, or something this exercise doesn’t describe.':r.answered?'No strong agreement emerged. Neutral answers and disagreement are useful information. You don’t need to adopt a role.':'You skipped every statement. There is no personal result to calculate, and you are welcome to keep exploring.'}</p><p class="fine" style="margin-top:16px">${r.answered} of 25 statements answered · Original, unvalidated reflection</p></div>${r.limited&&r.answered?'<div class="notice">You answered fewer than 15 statements. This is a limited snapshot, and skipping questions can change which themes appear.</div>':''}${r.ties.length>1&&r.signal?`<div class="notice green-notice">Your highest score is tied across ${r.ties.length} themes. The cards show up to three in the exercise’s fixed order; the full list below shows every tie. There isn’t a single winning label.</div>`:''}${r.top.length?`<div class="result-grid">${r.top.map(x=>`<section class="result-card"><span class="result-number">${x.score}<small style="font-size:.8rem">%</small></span><h2>${x.name}<span class="fine" style="display:block;margin-top:8px">${x.title}</span></h2><p>${x.description}</p><a class="text-link" href="#/learn/${x.article}">Explore the language </a></section>`).join('')}</div>`:''}<div class="scores-panel"><h2>Your full reflection</h2><p class="fine">Percentages are agreement points divided by the maximum available points for the statements you answered, weighted for each theme. A neutral answer contributes 50%. They are not population percentiles, compatibility scores, or a scientifically validated measure. Unanswered themes are omitted.</p>${r.ranked.map(x=>`<div class="score-row"><span>${x.name}</span><span class="score-track" aria-hidden="true"><span style="width:${x.score}%"></span></span><span>${x.score}%</span></div>`).join('')}<details><summary>What do these role words mean?</summary>${r.ranked.map(x=>`<p class="fine" style="margin:15px 0"><strong>${x.name}:</strong> ${x.description} <span class="muted">Based on ${x.items} answered statements.</span></p>`).join('')}<p class="fine">This nine-theme vocabulary is not exhaustive. Submission is represented through some narrower themes rather than a separate general result. You may prefer other language entirely.</p></details></div><div class="practice"><p class="eyebrow">CONSENT COMES WITH EVERY ROLE</p><p>All roles here refer to consenting adults. No title, score, or agreement overrides your right to set limits, stop, or leave. Learning about a dynamic does not make every related activity safe.</p><a href="#/learn/consent-in-practice" class="text-link" style="margin-top:20px">Consent in practice </a></div><div class="result-actions no-print"><button class="button pink-button" data-action="download-result" data-flow="dynamics">Save my reflection </button><button class="button secondary" data-action="print">Print</button><button class="button secondary" data-action="retake" data-flow="dynamics">Revisit my answers</button></div><p class="fine">Saved files contain sensitive preferences. Download only if you want a copy on this device.</p></div>`;}
const TOOLS=[{id:'conversation',name:'Conversation cards',description:'Twenty-four ways to open a gentler, deeper, or more curious conversation.'},{id:'check-in',name:'The ten-minute check-in',description:'Put words to what is present, what feels good, and what you need.'},{id:'boundaries',name:'Find your boundary words',description:'Turn an uncertain feeling into a clear, respectful sentence.'},{id:'reflection',name:'A little room to reflect',description:'Three prompts and a private page. Yours to keep or clear.'},{id:'care',name:'Prepare a care conversation',description:'Make a short note to bring to a qualified health professional.'},{id:'download',name:'Take the little toolkit',description:'A free printable companion with prompts, a check-in, and reflection space.'}];
function toolsPage(){title('The little intimacy toolkit');return `<div class="wrap section" style="padding-top:0">${pageHead('SMALL STEPS. REAL CONNECTION.','The little<br>intimacy toolkit.','Useful words, gentle prompts, and a little space to be human. Every tool is free. No email address or Vulpes Ignis account required.','connection-ribbons')}<div class="guidance-tools-cta"><div><p class="eyebrow">NOT SURE WHERE TO BEGIN?</p><h2>Ask a question. Find a useful next step.</h2><p>Ask Vulpes connects your question to existing guides, conversation prompts, and private tools.</p></div><a href="#/coach" class="button primary">Try Ask Vulpes</a></div><div class="tool-list">${TOOLS.map((t,i)=>`<a class="tool-item" href="#/tools/${t.id}"><span class="number">0${i+1}</span><h2>${t.name}</h2><p>${t.description}</p><span class="arrow" aria-hidden="true"></span></a>`).join('')}</div><p class="fine">Your notes stay in this tab’s session and aren’t sent to Vulpes Ignis. Browser session restore may retain them. Clear the session when you’re finished, especially on a shared device.</p></div>`;}
function field(label,key,value='',placeholder='',rows=3){return `<label for="field-${key}">${label}</label><textarea id="field-${key}" name="${key}" rows="${rows}" maxlength="5000" placeholder="${placeholder}">${escape(value)}</textarea>`;}
function textField(label,key,value='',placeholder=''){return `<label for="field-${key}">${label}</label><input id="field-${key}" name="${key}" type="text" maxlength="500" value="${escape(value)}" placeholder="${placeholder}">`;}
const toolTitle=id=>TOOLS.find(t=>t.id===id)?.name||'Your tool';
function toolPage(id){if(!TOOLS.some(t=>t.id===id))return notFound();title(toolTitle(id));let content='';
 if(id==='conversation'){const c=state.cards;content=`<div class="filters" aria-label="Choose a conversation style">${[['gentle','Start gently'],['deeper','Go a little deeper'],['curious','Follow curiosity']].map(([key,label])=>`<button class="filter ${c.level===key?'active':''}" aria-pressed="${c.level===key}" data-card-level="${key}">${label}</button>`).join('')}</div><div class="prompt-card" aria-live="polite"><span class="eyebrow">${c.index+1} OF 8 · ${c.level==='gentle'?'START GENTLY':c.level==='deeper'?'A LITTLE DEEPER':'FOLLOW CURIOSITY'}</span><p>${PROMPTS[c.level][c.index]}</p><span class="fine">An invitation. You can always pass.</span></div><div class="tool-controls"><button class="button secondary" data-action="card-prev"> Previous</button><button class="text-link" data-action="copy-card">Copy this prompt</button><button class="button primary" data-action="card-next">Next card </button></div><p class="fine" style="margin-top:25px">Ask whether the other person wants a conversation first. These cards do not create an obligation to disclose or participate.</p>`;}
 if(id==='check-in')content=`<form id="checkin-form" data-notes="checkin">${field('What has been taking up space for you?','present',state.checkin.present,'A feeling, a worry, or something on your mind…')}${field('What helped you feel connected or cared for?','connected',state.checkin.connected,'One small moment counts.')}${field('What is one manageable thing you would appreciate?','request',state.checkin.request,'Something specific, with room for a real answer.') }<div class="button-row"><button class="button primary" type="submit">Make my check-in note </button><button class="button secondary" type="button" data-action="clear-note" data-note="checkin">Clear these notes</button></div></form><div id="tool-output" aria-live="polite"></div>`;
 if(id==='boundaries')content=`<form id="boundary-form" data-notes="boundary">${textField('What are you comfortable with?','yes',state.boundary.yes,'Talking about this when we both have time')}${textField('What are you not available for?','no',state.boundary.no,'Being pressured to answer right away')}${textField('What will you do to honor your limit?','action',state.boundary.action,'Pause and return when I’m ready')}<p class="fine" style="margin-bottom:22px">Describe an action you control. A boundary is not permission to control someone else.</p><div class="button-row"><button class="button primary" type="submit">Find my words </button><button class="button secondary" type="button" data-action="clear-note" data-note="boundary">Clear these notes</button></div></form><div id="tool-output" aria-live="polite"></div>`;
 if(id==='reflection')content=`<form id="reflection-form" data-notes="notes">${field('What am I noticing?','notice',state.notes.notice,'A feeling, a preference, a question…')}${field('What am I curious about?','curious',state.notes.curious,'There is no obligation to act on an idea.')}${field('What is one kind next step?','next',state.notes.next,'A conversation, a guide, a pause, or something else…')}<div class="button-row"><button class="button primary" type="submit">Download my reflection </button><button class="button secondary" type="button" data-action="clear-note" data-note="notes">Clear these notes</button></div><p class="fine" style="margin-top:19px">Typing keeps your draft within this tab’s session. Download creates a text file on your device.</p></form>`;
 if(id==='care')content=`<p class="muted" style="font-size:.9rem;margin-bottom:25px">A note you can bring to a clinician. You don’t need to identify the cause before asking for help. Don’t enter names, addresses, or information you don’t want on this device.</p><form id="care-form" data-notes="care">${field('What changed, or what would you like to discuss?','concern',state.care.concern,'A short description in your own words')}${textField('When did you notice it, and how often does it happen?','timing',state.care.timing,'Approximate timing is enough')}${field('What questions would you like answered?','questions',state.care.questions,'What could help us understand this? What are my options?')}<div class="button-row"><button class="button primary" type="submit">Make my care note </button><button class="button secondary" type="button" data-action="clear-note" data-note="care">Clear these notes</button></div></form><div id="tool-output" aria-live="polite"></div><div class="notice">This tool prepares a note; it does not assess symptoms or urgency. If you think you’re having an emergency, use local emergency medical services.</div>`;
 if(id==='download')content=`<div class="book" style="margin:5px auto 45px;transform:rotate(-6deg)" aria-hidden="true"><small>VULPES IGNIS</small><span>The little<br>intimacy<br>toolkit.</span><b>✳</b><small>SMALL STEPS. REAL CONNECTION.</small></div><h2>A little connection, to take with you.</h2><p class="muted" style="font-size:.92rem">Inside: twelve conversation starters, a ten-minute check-in, a boundary prompt, and room for private reflection. Use it alone or share it with a willing adult partner.</p><p class="fine" style="margin-top:18px">An original educational resource. No personal results or notes are included in this download.</p><div class="button-row" style="margin-top:28px"><a class="button primary" href="assets/The-Little-Intimacy-Toolkit.pdf" download>Download free PDF </a><button class="button secondary" data-action="toolkit-html">Printable web version </button></div><p class="fine" style="margin-top:20px">The web version opens as a saved HTML file. Print it from your browser, or choose “Save as PDF.”</p>`;
 return `<div class="wrap"><div class="illustrated-head tool-head"><div class="page-hero compact"><a class="back-link" href="#/tools"> Back to the toolkit</a><p class="eyebrow">SMALL STEPS. YOUR PACE.</p><h1>${toolTitle(id)}</h1></div>${artPanel(TOOL_ART[id])}</div><section class="tool-panel">${content}</section></div>`;}
function about(){title('Our story');return `<div class="wrap">${pageHead('A LITTLE FIRE. A LOT OF HUMANITY.','Because these questions<br>deserve a kinder place.','Vulpes Ignis exists to help adults feel seen, understood, and able to make informed choices about intimacy and wellbeing.','garden-bloom')}<div class="about-grid"><div class="article-body"><h2 style="margin-top:0">A space built around people.</h2><p>Questions about intimacy rarely arrive neatly packaged. Sometimes they sound practical. Sometimes they sound like “Is it just me?” Sometimes they stay unasked for years.</p><p>Myke created Vulpes Ignis to make room for those questions: with clear education, useful tools, a little humor, and respect for the person asking. A fox’s curiosity. A fire’s warmth. Something you can actually use when you leave.</p><h2>Wisdom with its sleeves rolled up.</h2><p>Our aim is to help you understand something, find a sentence you can say, or choose a manageable next step. You don’t have to share our vocabulary, adopt a label, buy a product, or tell us your history.</p><p>Individuals, couples, adults in different relationship structures, people rebuilding trust, and people exploring something new are welcome. Your pace and boundaries belong to you.</p><h2>Clear about what we offer.</h2><p>This first edition offers original educational guides and private, rule-based tools. Vulpes Ignis is not a medical clinic or a licensed therapy service. Health-related articles link to primary sources and have not been clinically reviewed.</p><p>The longer vision includes reviewed community contributions, coaching, learning products, and carefully scoped AI assistance. Each needs its own real setup before we call it available.</p><a class="text-link" href="#/community">See what’s here and what’s next </a></div><aside class="about-note"><p class="eyebrow" style="margin-bottom:20px">WHAT WE COME BACK TO</p><h2>Connection over<br>perfection.</h2><p>Choice before pressure.<br>Clarity before cleverness.<br>Care before commerce.</p><p>And just enough humor to remember that being human is a fairly ridiculous group project.</p><a class="text-link" href="#/learn" style="margin-top:25px">Find something useful </a></aside></div></div>`;}
function guidanceResult(){
  if(!state.coach.shown)return '';
  const result=answerQuestion(state.coach.question||'',state.coach.topic||'auto');
  const guides=result.guides.map(id=>ARTICLES.find(a=>a.id===id)).filter(Boolean);
  const focus=['step','words','read'].includes(state.coach.focus)?state.coach.focus:'step';
  const label=result.safety?'SAFETY FIRST':result.matched?'A STARTING POINT FROM OUR LIBRARY':'NO RELIABLE TOPIC MATCH';
  let panel='';
  if(result.matched){
    if(focus==='step')panel=`<div class="guidance-view" id="guidance-view" aria-label="One small step">
      <p class="eyebrow">ONE USEFUL NEXT STEP</p><p>${escape(result.action)}</p>
      <p class="eyebrow">A QUESTION TO THINK ABOUT</p><p>${escape(result.reflection)}</p>
      <p class="fine">You can reflect privately. Nothing needs to be submitted or downloaded.</p>
      </div>`;
    if(focus==='words')panel=`<div class="guidance-view" id="guidance-view" aria-label="Conversation wording">
      <label class="eyebrow" for="guidance-draft">WORDS YOU CAN MAKE YOUR OWN</label>
      <textarea id="guidance-draft" rows="5" maxlength="2000" aria-describedby="guidance-draft-note">${escape(typeof state.coach.draft==='string'?state.coach.draft:result.starter)}</textarea>
      <p id="guidance-draft-note" class="fine">Edit before sharing. This is a suggested conversation opener, not an instruction to agree or participate.</p>
      <button type="button" class="button secondary" data-action="copy-guidance">Copy my edited wording</button>
      </div>`;
    if(focus==='read')panel=`<div class="guidance-view" id="guidance-view" aria-label="Related guides">
      <p class="eyebrow">KEEP LEARNING</p>
      ${guides.length?`<ul class="guidance-related">${guides.map(a=>`<li><a href="#/learn/${encodeURIComponent(a.id)}">${escape(a.title)}</a></li>`).join('')}</ul>`:'<p>The related guides are currently unavailable.</p>'}
      <div class="guidance-actions"><a class="button primary" href="#/tools/${encodeURIComponent(result.tool)}">Try a related practical tool</a><a class="button secondary" href="#/learn">Browse the library</a></div>
      </div>`;
  }
  return `<section class="guidance-result" id="guidance-result" tabindex="-1" aria-label="Your educational starting point">
    <p class="eyebrow">${label}</p>
    <h3>${escape(result.label)}</h3>
    <p>${escape(result.summary)}</p>
    ${result.matched?`<p class="guidance-explanation"><strong>Why this appeared:</strong> ${escape(result.why)}</p>`:''}
    ${result.matched&&result.alternatives.length?`<div class="guidance-alternates"><p class="eyebrow">ALSO RELATED</p><div class="guidance-actions">${result.alternatives.map(a=>`<button type="button" class="button secondary" data-action="guidance-topic" data-guidance-topic="${escape(a.id)}">${escape(a.label)}</button>`).join('')}</div></div>`:''}
    ${result.matched?`<div class="guidance-views" role="group" aria-label="Choose what helps next">
      ${[['step','A small next step'],['words','Words to use'],['read','Related reading']].map(([id,text])=>`<button type="button" data-action="guidance-focus" data-focus="${id}" aria-pressed="${focus===id}" class="guidance-view-button ${focus===id?'selected':''}">${text}</button>`).join('')}
      </div>${panel}`:`<div class="notice ${result.safety?'':'green-notice'}" role="note"><p class="eyebrow">${result.safety?'A SAFER NEXT STEP':'WHAT YOU CAN DO'}</p><p>${escape(result.action)}</p></div>
      ${!result.safety?'<p class="fine">You can choose a topic above instead. Unsupported questions will not receive a made-up answer.</p>':''}`}
    <p class="guidance-disclaimer">This guidance comes from fixed topic rules and existing educational content, not AI, a live coach, or a medical assessment. Your question stays in this browser tab. Copied text can remain on the clipboard after clearing the session.</p>
  </section>`;
}
function coach(){
 title('Ask Vulpes');
 return `<div class="wrap section" style="padding-top:0">
   ${pageHead('ASK VULPES · FREE GUIDANCE','Find a useful next step.','Explore your question with a small, transparent topic guide. Choose an action, adapt a conversation opener, or find related reading. No paid AI or live coaching.','conversation-chairs')}
   <section class="tool-panel guidance-panel" aria-labelledby="guidance-title">
     <p class="eyebrow">ASK VULPES</p><h2 id="guidance-title">What is on your mind?</h2>
     <p class="guidance-explain">Questions are matched to our published learning topics by fixed rules. Nothing is submitted to us or an outside AI. This is educational guidance, not a diagnosis or emergency response.</p>
     <div class="guidance-quick" aria-label="Quick starting topics">
       <p class="eyebrow">START WITH A TOPIC</p>
       <div class="guidance-actions">
       ${[['communication','Have a conversation'],['desire','Different desires'],['boundaries','Set a boundary'],['health','Comfort and care']].map(([id,label])=>`<button type="button" class="button secondary" data-action="guidance-quick" data-guidance-topic="${id}">${label}</button>`).join('')}
       </div>
     </div>
     <form id="guidance-form">
       <label for="guidance-question">Or type your question</label>
       <textarea id="guidance-question" name="question" maxlength="1500" rows="4" placeholder="Example: How do I talk to my partner about wanting more affection?">${escape(state.coach.question||'')}</textarea>
       <label for="guidance-topic">Choose a topic yourself (optional)</label>
       <select id="guidance-topic" name="topic"><option value="auto">Match my question to a topic</option>${GUIDANCE_CHOICES.map(t=>`<option value="${escape(t.id)}" ${state.coach.topic===t.id?'selected':''}>${escape(t.label)}</option>`).join('')}</select>
       <p class="guidance-choices">If the automatic match doesn't fit, select a different topic. Clear safety warnings cannot be overridden.</p>
       <div class="button-row"><button type="submit" class="button primary">Find a starting point</button><button type="button" class="button secondary" data-action="clear-guidance">Clear my question</button></div>
     </form>
     ${guidanceResult()}
   </section>
   <section aria-labelledby="guidance-faq-title"><h2 id="guidance-faq-title">Common questions, with clear answers</h2><div class="faq">${COACH_FAQ.map(([q,a])=>`<details><summary>${escape(q)}</summary><p>${escape(a)}</p></details>`).join('')}</div></section>
 </div>`;
}
function community(){title('Community & what’s next');return `<div class="wrap section" style="padding-top:0">${pageHead('GROWING WITH INTENTION','A place to return to.<br>Built one real step at a time.','The vision is a thoughtful community around adult wellness, connection, and honest questions. Here is what you can use today, and what still needs to be built.')}<div class="status-list">${[
 ['The library & toolkit','Read original guides, use conversation tools, and download the free intimacy toolkit.','Available now',true],
 ['Private self-discovery','Find learning paths or explore adult dynamics. Your answers stay in your tab’s session.','Available now',true],
 ['The Vulpes Ignis letter','Useful ideas, new guides, and a little perspective. Newsletter signup and email delivery are not connected yet.','Planned',false],
 ['Community spaces','Facebook, Discord, and on-site discussion are part of the vision. No official community invite or live forum is connected to this edition.','Planned',false],
 ['Coaching & reader questions','Ask Vulpes offers rule-based article suggestions and practice prompts. Live coaching, question submission, and reader contributions are not open yet.','In preparation',false],
 ['Courses, guides & curated products','The free toolkit is ready. Paid offerings, checkout, and fulfillment need setup before sales can begin. No payment is taken here.','Planned',false],
 ['AI assistance','The current assessments use transparent rules. A live AI conversation service and its privacy controls are not connected.','Planned',false]
 ].map(([h,p,b,ready])=>`<div class="status-row"><div><h3>${h}</h3><p>${p}</p></div><span class="badge ${ready?'':'future'}">${b}</span></div>`).join('')}</div><a class="button primary" href="#/tools">Use the free toolkit </a></div>`;}
const LEGAL={privacy:{title:'Your curiosity deserves privacy.',eyebrow:'YOUR PRIVACY',intro:'A plain-language description of this edition, updated November 20, 2026.',body:`<h2>What the tools keep</h2><p>Your adult confirmation, assessment answers, results, typed notes, saved guide choices, last opened guide, and guided-path progress are kept in your browser tab’s session storage. This helps you move between pages without losing your place. We do not send these choices, answers, or notes to Vulpes Ignis or an AI service. If session saving is blocked, your choices last only until this page reloads.</p><p>Closing a tab usually ends its session, but browsers can restore sessions. Use “Clear my private session” to explicitly remove this site’s session data. Nothing is stored by these tools in permanent browser local storage.</p><h2>Downloads and printing</h2><p>Saving a reflection, downloading notes, or printing creates a copy outside this page’s session. Those files remain on your device, in your downloads, backups, print queue, or chosen destination until you remove them. Shared devices need particular care.</p><h2>Hosting and access</h2><p>This publicly accessible educational website is hosted on GitHub Pages. Visitors do not need a GitHub or ChatGPT account. GitHub may process technical request information, such as IP addresses and service logs, under its own privacy policies. The reflection tools keep answers and notes in this browser tab rather than sending them to Vulpes Ignis.</p><p>This edition includes no site-added analytics, ad trackers, embedded social feeds, advertising cookies, or third-party web fonts. GitHub hosting has its own technical logging and storage.</p><h2>External links and quick exit</h2><p>External resources have their own privacy policies. We suppress referral information on external links. Quick exit removes this site’s browser-tab session data and opens Wikipedia. It cannot erase browser history, downloaded files, copies placed on the clipboard, or other tabs.</p><h2>Questions and email</h2><p>No questions, email addresses, or payment details are collected by forms in this edition. Ask Vulpes matches your question to predefined educational topics in your browser and links to existing guides. It does not send your question to anyone or provide live coaching. Newsletter delivery, coaching submissions, community accounts, and payments are not active.</p><h2>Your controls</h2><p>You can skip questions, browse without taking an assessment, download selectively, or clear your session, including saved guides and path progress. Keep only what you want to keep.</p><p><button class="button secondary clear-session">Clear my private session</button></p>`},terms:{title:'A few shared understandings.',eyebrow:'TERMS OF USE',intro:'For this first edition of Vulpes Ignis, updated October 28, 2026.',body:`<h2>Adults only</h2><p>This site’s adult intimacy and wellness content is intended for people aged 18 and older. The entry confirmation is self-attestation, not identity verification. All discussion of relationship dynamics concerns consenting adults.</p><h2>Educational use</h2><p>Guides and tools provide general education and reflection. They do not establish a clinical, therapeutic, or coaching relationship. You are responsible for deciding what you read, save, share, or try. You can stop an exercise at any time.</p><h2>Assessments</h2><p>Both assessments use original, unvalidated rules. They are not medical tests, diagnostic instruments, compatibility measures, or proof of identity. Results can change with your answers and the questions you skip. A result never creates consent or tells you that an activity is safe.</p><h2>Resources and ownership</h2><p>You may download, print, and share the free toolkit for personal, noncommercial use with attribution to Vulpes Ignis. Do not present these materials as medical advice or resell them as your own. Other content and third-party sources retain their respective ownership.</p><h2>Availability</h2><p>This is an initial educational edition. Planned services are labeled as planned. It does not take payments, accept coaching submissions, or operate a public forum. Resources may be revised or withdrawn as the project develops.</p><h2>External sources</h2><p>External links are offered for further learning. Their contents, availability, and policies are controlled by their publishers. No endorsement of a product or clinical service is implied.</p>`},disclaimer:{title:'Clarity is part of care.',eyebrow:'EDUCATIONAL DISCLAIMER',intro:'What this site can offer, and where professional support belongs.',body:`<h2>Education and reflection</h2><p>Vulpes Ignis offers general adult intimacy, relationship, and wellness education. Content has not been clinically reviewed. We do not diagnose conditions, prescribe treatment, assess emergencies, or provide licensed psychotherapy through this site.</p><h2>Health concerns</h2><p>For persistent, severe, or worrying symptoms, consult a qualified healthcare professional. Do not change prescribed medication based on a guide or assessment. This site cannot determine what is causing pain, a change in sexual function, or a change in desire.</p><p>If you think you are experiencing an emergency, use local emergency medical services. Nothing entered into these tools is monitored or sent to a response team.</p><h2>Your choice stays yours</h2><p>You can decline any question or exercise. Consent must remain freely chosen, specific, informed, and reversible. No relationship status, role label, score, or prior agreement overrides a person’s autonomy.</p><h2>Assessment limits</h2><p>The learning-path assessment recommends resources from stated answer weights. The adult-dynamics reflection summarizes agreement with original statements across nine non-exhaustive themes. Neither tool has been scientifically validated. The dynamics percentages are agreement calculations, not population percentiles.</p><h2>Sources and updates</h2><p>Health-related guides link to primary sources where used. Source guidance can change. Reading a cited source does not replace an individual assessment by an appropriately qualified professional.</p><a class="text-link" href="#/tools/care">Prepare questions for care </a>`}};
function legal(id){title(id==='privacy'?'Your privacy':id==='terms'?'Terms of use':'Educational disclaimer');const p=LEGAL[id];return `<div class="wrap">${pageHead(p.eyebrow,p.title,p.intro)}<article class="legal">${p.body}</article></div>`;}
function notFound(){title('A different path');return `<div class="wrap section">${pageHead('A DIFFERENT PATH','This page wandered off.','The link may be incomplete. There’s still plenty to explore.')}<a href="#/" class="button primary">Back to the beginning </a></div>`;}
function route(){const raw=location.hash.slice(1)||'/';const [path,query]=raw.split('?');return {path,params:new URLSearchParams(query||'')};}
function render({scroll=false,focus=false}={}){const{path,params}=route();if(path.startsWith('/learn/')){const id=path.slice(7);if(ARTICLES.some(a=>a.id===id)){state.space.lastGuide=id;persist();}}if(path==='/')main.innerHTML=home();else if(path==='/paths'){title('A place to begin');main.innerHTML=pathsPage(state.space);}else if(path.startsWith('/paths/')){const page=pathPage(state.space,path.slice(7));title(getPath(path.slice(7))?.name||'Your guided path');main.innerHTML=page||notFound();}else if(path==='/my-space'){title('My space');main.innerHTML=mySpace(state.space,state,card);}else if(path==='/learn'){if(params.has('topic')){const t=params.get('topic');state.filter=CATEGORIES.includes(t)?t:'All topics';}main.innerHTML=library();$('#library-count').textContent=`${matchingArticles().length} ${matchingArticles().length===1?'guide':'guides'} to explore`;}else if(path.startsWith('/learn/'))main.innerHTML=articlePage(path.slice(7));else if(path.startsWith('/activity/')){const id=path.slice(10);title(getActivity(id)?.title||'Activity unavailable');main.innerHTML=renderActivity(id,state);}else if(path==='/explore')main.innerHTML=explore();else if(path==='/assessment')main.innerHTML=state.journey.active?quiz('journey'):assessmentIntro('journey');else if(path==='/dynamics')main.innerHTML=state.dynamics.active?quiz('dynamics'):assessmentIntro('dynamics');else if(path==='/results')main.innerHTML=journeyResults();else if(path==='/dynamics-results')main.innerHTML=dynamicsResults();else if(path==='/tools')main.innerHTML=toolsPage();else if(path.startsWith('/tools/'))main.innerHTML=toolPage(path.slice(7));else if(path==='/about')main.innerHTML=about();else if(path==='/coach')main.innerHTML=coach();else if(path==='/community')main.innerHTML=community();else if(LEGAL[path.slice(1)])main.innerHTML=legal(path.slice(1));else main.innerHTML=notFound();main.innerHTML+=pathReturn(state.space,path);if(!sessionStorageAvailable)main.insertAdjacentHTML('afterbegin','<div class="wrap"><p class="notice" role="status">This browser is blocking session saving. Your choices will last only until this page reloads. You can download a reading list to keep it.</p></div>');for(const a of document.querySelectorAll('[data-nav]')){const active=a.dataset.nav==='/'?path==='/':a.dataset.nav==='/explore'?['/explore','/assessment','/results','/dynamics','/dynamics-results'].includes(path):path.startsWith(a.dataset.nav);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');}if(path.startsWith('/activity/'))attachActivityHandlers(path.slice(10),state,persist,toast,download,copy,selector=>{render();document.querySelector(selector)?.focus({preventScroll:true});});if(scroll)window.scrollTo({top:0,behavior:'instant'});if(focus&&!$('#adult-dialog').open)main.focus({preventScroll:true});}
function advance(type,skip=false){const f=state[type],qs=type==='dynamics'?DYNAMIC_QUESTIONS:QUESTIONS;if(skip)delete f.answers[qs[f.step].id];if(f.step===qs.length-1){f.completed=true;f.active=false;persist();location.hash=type==='dynamics'?'#/dynamics-results':'#/results';}else{f.step++;persist();render({scroll:true,focus:true});}}
let outputText='';
function toolOutput(text){outputText=text;$('#tool-output').innerHTML=`<h2 style="margin-top:35px">Your words, with room to adjust.</h2><div class="copy-output">${escape(text)}</div><div class="button-row"><button class="button secondary" data-action="copy-output">Copy my note</button><button class="button primary" data-action="download-output">Download my note </button></div>`;$('#tool-output').scrollIntoView({behavior:'smooth',block:'nearest'});}
function resultText(type){if(type==='dynamics'){const r=scoreDynamics(state.dynamics.answers);return `VULPES IGNIS · YOUR ADULT DYNAMICS REFLECTION\n\n${r.answered}/25 statements answered. ${r.limited?'Limited answer coverage.':''}\n\n${r.ranked.map(x=>`${x.name}: ${x.score}% agreement\n${x.description}`).join('\n\n')}\n\nThis original exercise is unvalidated. Percentages describe agreement in answered statements, not identity, compatibility, or population rank. Skipped questions can change results. Ties use fixed ordering and do not indicate a single winner. All roles refer to consenting adults; consent and autonomy remain essential.\n\nThis file stays on your device after the website session is cleared.`;}const r=assess(state.journey.answers);return `VULPES IGNIS · YOUR LEARNING PATHS\n\n${r.answered}/${QUESTIONS.length} questions answered.\n\n${r.paths.map((p,i)=>`${i+1}. ${p.name}\n${p.reason}\nGuide: ${ARTICLES.find(a=>a.id===p.article).title}`).join('\n\n')}\n\n${r.comfortNote||''}\n\nThese are educational suggestions from transparent rules, not a diagnosis or urgency assessment. Your full answers are not included in this copy. This file remains on your device after the website session is cleared.`;}
function toolkitHTML(){const qs=[...PROMPTS.gentle.slice(0,6),...PROMPTS.deeper.slice(0,4),...PROMPTS.curious.slice(0,2)];return `<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>The Little Intimacy Toolkit · Vulpes Ignis</title><style>body{max-width:760px;margin:50px auto;padding:0 30px;font:16px/1.8 Georgia,serif;color:#252d21;background:#fffef8}h1{font-size:48px;line-height:1.1}h2{font-size:28px;margin-top:40px}small{font:11px Arial,sans-serif;letter-spacing:2px}li{padding:5px}.line{border-bottom:1px solid #aab09e;height:45px}section{break-inside:avoid}.note{font:13px/1.8 Arial,sans-serif;border-left:2px solid #a0ad84;padding-left:18px}@media print{body{margin:0;padding:0}h1{font-size:38px}section{page-break-inside:avoid}}</style><small>VULPES IGNIS · ADULTS 18+</small><h1>The little<br>intimacy toolkit.</h1><p>Small steps. Real connection. Yours to use alone or with a willing adult partner.</p><p class="note">Education and reflection, not medical care or therapy. Every prompt is optional. Ask before sharing, make room for a no, and stop any activity that hurts or feels unwanted.</p><section><h2>A little conversation</h2><ol>${qs.map(q=>`<li>${q}</li>`).join('')}</ol></section><section><h2>The ten-minute check-in</h2><p>Choose a time everyone agrees to. Take turns listening without rushing to fix.</p><ol><li>What has been taking up space for you?</li><li>When did you feel connected or cared for?</li><li>What is one manageable thing you would appreciate next week?</li></ol><p>Finish by agreeing on one freely chosen, specific next step. Connection does not create an obligation to be sexually intimate.</p></section><section><h2>Words for a boundary</h2><p>“I’m comfortable with ____. I’m not available for ____. To honor that limit, I will ____.”</p><p>Choose an action you control. Your boundary can change as you learn what you need.</p><div class="line"></div><div class="line"></div></section><section><h2>A little room to reflect</h2><p>What am I noticing?</p><div class="line"></div><p>What am I curious about?</p><div class="line"></div><p>What is one kind next step?</p><div class="line"></div></section><p class="note" style="margin-top:40px">You don’t need a label, a partner, or a perfect answer to deserve understanding. For health concerns, ask a qualified clinician. This resource does not diagnose or assess emergencies.</p><small>© 2026 VULPES IGNIS · PERSONAL, NONCOMMERCIAL USE WITH ATTRIBUTION</small></html>`;}
// Event delegation keeps every routed view keyboard-accessible and avoids duplicate handlers.
document.addEventListener('click',e=>{if(e.target.closest('.skip')){e.preventDefault();main.focus();main.scrollIntoView();return;}const scrollLink=e.target.closest('[data-scroll]');if(scrollLink){e.preventDefault();const heading=document.getElementById(scrollLink.dataset.scroll);if(heading){heading.setAttribute('tabindex','-1');heading.focus({preventScroll:true});heading.scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});}return;}const menu=e.target.closest('.menu-button');if(menu){const open=menu.getAttribute('aria-expanded')==='true';menu.setAttribute('aria-expanded',String(!open));menu.setAttribute('aria-label',open?'Open navigation':'Close navigation');$('#mobile-nav').hidden=open;return;}if(e.target.closest('#mobile-nav a')){closeMenu();}if(e.target.closest('.clear-session')){$('#confirm-dialog').showModal();return;}const filter=e.target.closest('[data-filter]');if(filter){state.filter=filter.dataset.filter;const p=route();if(p.params.has('topic'))history.replaceState(null,'','#/learn');render();document.querySelector(`[data-filter="${CSS.escape(state.filter)}"]`)?.focus();return;}const level=e.target.closest('[data-card-level]');if(level){state.cards={level:level.dataset.cardLevel,index:0};render();document.querySelector(`[data-card-level="${state.cards.level}"]`)?.focus();return;}const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,type=b.dataset.flow;
 if(a==='choose-path'){state.space=choosePath(state.space,b.dataset.path);persist();render();document.querySelector('.path-compass .button')?.focus();toast('Your path is ready. Take it at your own pace.');}
 else if(a==='toggle-save'){const id=b.dataset.guide;state.space=saveGuide(state.space,id);persist();render();(document.querySelector(`[data-action="toggle-save"][data-guide="${CSS.escape(id)}"]`)||main).focus({preventScroll:true});toast(state.space.saved.includes(id)?'Guide saved in this tab’s session.':'Guide removed from your saved list.');}
 else if(a==='saved-only'){state.savedOnly=!state.savedOnly;render();document.querySelector('[data-action="saved-only"]')?.focus({preventScroll:true});}
 else if(a==='download-reading-list'){download('Vulpes-Ignis-My-Reading-List.txt',readingListText(state.space));toast('Your reading list has been downloaded.');}
 else if(a==='start'){state[type].active=true;persist();render({scroll:true,focus:true});}
 else if(a==='next')advance(type);
 else if(a==='skip')advance(type,true);
 else if(a==='back'){if(state[type].step)state[type].step--;else state[type].active=false;persist();render({scroll:true,focus:true});}
 else if(a==='retake'){state[type].active=true;state[type].step=0;persist();location.hash=type==='dynamics'?'#/dynamics':'#/assessment';}
 else if(a==='download-result'){download(type==='dynamics'?'Vulpes-Ignis-Dynamics-Reflection.txt':'Vulpes-Ignis-My-Learning-Paths.txt',resultText(type));toast('Your reflection has been downloaded.');}
 else if(a==='print')window.print();
 else if(a==='reset-search'){state.search='';state.filter='All topics';state.savedOnly=false;history.replaceState(null,'','#/learn');render();$('#library-search').focus();}
 else if(a==='card-next'||a==='card-prev'){const step=a==='card-next'?1:-1;state.cards.index=(state.cards.index+step+8)%8;render();document.querySelector(`[data-action="${a}"]`)?.focus();}
 else if(a==='copy-card')copy(PROMPTS[state.cards.level][state.cards.index]);
 else if(a==='copy-output')copy(outputText);
 else if(a==='download-output'){download('Vulpes-Ignis-Private-Note.txt',outputText);toast('Your private note has been downloaded.');}
 else if(a==='clear-note'){state[b.dataset.note]={};persist();outputText='';render();toast('These notes have been cleared.');}
 else if(a==='clear-guidance'){state.coach={};persist();render();document.getElementById('guidance-question')?.focus();toast('Question cleared from this tab.');}
 else if(a==='guidance-quick'||a==='guidance-topic'){const id=b.dataset.guidanceTopic;if(!GUIDANCE_CHOICES.some(x=>x.id===id))return;state.coach={question:state.coach.question||'',topic:id,shown:true,focus:'step'};persist();render();document.getElementById('guidance-result')?.focus({preventScroll:true});document.getElementById('guidance-result')?.scrollIntoView({behavior:'auto',block:'start'});}
 else if(a==='guidance-focus'){const focus=b.dataset.focus;if(!['step','words','read'].includes(focus)||!state.coach.shown)return;state.coach.focus=focus;persist();render();document.querySelector('[data-action="guidance-focus"][data-focus="'+focus+'"]')?.focus({preventScroll:true});document.getElementById('guidance-result')?.scrollIntoView({behavior:'auto',block:'start'});}
 else if(a==='copy-guidance'){const textarea=document.getElementById('guidance-draft');if(!textarea)return;const text=textarea.value;if(!text.trim()){toast('Add some wording before copying.');textarea.focus();return;}if(navigator.clipboard?.writeText){navigator.clipboard.writeText(text).then(()=>toast('Edited wording copied.')).catch(()=>{textarea.focus();textarea.select();toast('Select the text and copy it manually.');});}else{textarea.focus();textarea.select();toast('Select the text and copy it manually.');}}
 else if(a==='toolkit-html'){download('The-Little-Intimacy-Toolkit.html',toolkitHTML(),'text/html;charset=utf-8');toast('Your printable toolkit has been downloaded.');}
});
function closeMenu(){$('#mobile-nav').hidden=true;$('.menu-button').setAttribute('aria-expanded','false');$('.menu-button').setAttribute('aria-label','Open navigation');}
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#mobile-nav').hidden){closeMenu();$('.menu-button').focus();}});
document.addEventListener('change',e=>{if(e.target.matches('[data-path-step]')){const checkbox=e.target;state.space=markStep(state.space,checkbox.dataset.path,checkbox.dataset.pathStep,checkbox.checked);persist();const id=checkbox.id;render();document.getElementById(id)?.focus({preventScroll:true});return;}if(e.target.matches('input[name="quiz-answer"]')){const type=e.target.dataset.flow;const qs=type==='dynamics'?DYNAMIC_QUESTIONS:QUESTIONS;const value=e.target.value;state[type].answers[qs[state[type].step].id]=type==='dynamics'?Number(value):value;persist();render();document.querySelector(`input[name="quiz-answer"][value="${CSS.escape(value)}"]`)?.focus({preventScroll:true});}});
document.addEventListener('input',e=>{if(e.target.id==='library-search'){state.search=e.target.value;$('#library-results').innerHTML=filteredArticles();const n=matchingArticles().length;$('#library-count').textContent=`${n} ${n===1?'guide':'guides'} to explore`;return;}const form=e.target.closest('form[data-notes]');if(form){const key=form.dataset.notes;state[key][e.target.name]=e.target.value;persist();}});
document.addEventListener('input',e=>{
   if(e.target.id==='guidance-draft'){state.coach.draft=e.target.value.slice(0,2000);persist();return;}
   if(!e.target.closest('#guidance-form'))return;
   const form=e.target.form;
   const fields=Object.fromEntries(new FormData(form));
   state.coach={question:String(fields.question||'').slice(0,1500),topic:GUIDANCE_CHOICES.some(x=>x.id===fields.topic)?fields.topic:'auto',shown:false,focus:'step'};
   persist();
   document.getElementById('guidance-result')?.remove();
 });
 document.addEventListener('submit',e=>{
 const form=e.target;
 if(form.id==='guidance-form'){
   e.preventDefault();
   const values=Object.fromEntries(new FormData(form));
   const question=String(values.question||'').trim().slice(0,1500);
   const topic=GUIDANCE_CHOICES.some(x=>x.id===values.topic)?values.topic:'auto';
   if(!question&&topic==='auto'){toast('Write a question or choose a topic to explore.');form.querySelector('#guidance-question')?.focus();return;}
   state.coach={question,topic,shown:true,focus:'step'};
   persist();render();
   const result=document.getElementById('guidance-result');
   if(result){result.focus({preventScroll:true});result.scrollIntoView({behavior:'auto',block:'start'});}
   return;
 }
 if(!form.matches('form[data-notes]'))return;e.preventDefault();const values=Object.fromEntries(new FormData(form));state[form.dataset.notes]=values;persist();if(!Object.values(values).some(v=>v.trim())){toast('Add a thought first, or leave this exercise for another day.');form.querySelector('textarea,input')?.focus();return;}
 if(form.id==='checkin-form')toolOutput(`A LITTLE CHECK-IN\n\nWhat’s taking up space:\n${values.present||'(Left open)'}\n\nWhat helped me feel connected:\n${values.connected||'(Left open)'}\n\nOne thing I’d appreciate:\n${values.request||'(Left open)'}\n\nAn invitation, with room for a real answer.`);
 if(form.id==='boundary-form')toolOutput(`${values.yes?'I’m comfortable with '+values.yes+'. ':''}${values.no?'I’m not available for '+values.no+'. ':''}${values.action?'To honor that limit, I will '+values.action+'.':''}\n\nA starting point in your own words. Adjust it until it sounds like you.`);
 if(form.id==='care-form')toolOutput(`MY QUESTIONS FOR CARE\n\nWhat I’d like to discuss:\n${values.concern||'(Left open)'}\n\nTiming and frequency:\n${values.timing||'(Left open)'}\n\nWhat I’d like to understand:\n${values.questions||'(Left open)'}\n\nThis is my own note, not a diagnosis or urgency assessment.`);
 if(form.id==='reflection-form'){download('Vulpes-Ignis-Private-Reflection.txt',`A LITTLE ROOM TO REFLECT\n\nI notice:\n${values.notice||''}\n\nI’m curious about:\n${values.curious||''}\n\nOne kind next step:\n${values.next||''}\n\nA private reflection from Vulpes Ignis. This file remains on your device after you clear the website session.`);toast('Your reflection has been downloaded.');}
});
$('#adult-dialog').addEventListener('cancel',e=>e.preventDefault());
$('#adult-dialog').addEventListener('close',()=>{if($('#adult-dialog').returnValue==='yes'){adult=true;try{sessionStorage.setItem('vi-adult','yes');}catch{}main.focus({preventScroll:true});}else if(!adult)$('#adult-dialog').showModal();});
// Quick exit clears this tab's reflections and replaces the browser
// history entry, instead of leaving sensitive information behind on Back.
$('.quick-exit').addEventListener('click', e => {
  e.preventDefault();
  try {
    sessionStorage.removeItem('vi-session');
    sessionStorage.removeItem('vi-adult');
  } catch {}
  window.location.replace('https://www.wikipedia.org/');
});
$('#confirm-dialog').addEventListener('close',()=>{if($('#confirm-dialog').returnValue!=='clear')return;try{sessionStorage.removeItem('vi-session');sessionStorage.removeItem('vi-adult');}catch{}adult=false;state.space=emptySpace();state.savedOnly=false;state.search='';state.filter='All topics';state.cards={level:'gentle',index:0};state.journey=blankFlow();state.dynamics=blankFlow();state.activityAnswers={};for(const k of ['notes','checkin','boundary','care','coach'])state[k]={};outputText='';render({scroll:true});$('#adult-dialog').returnValue='';$('#adult-dialog').showModal();toast('Private answers, notes, saved guides, and path progress cleared. Downloaded files are unchanged.');});
window.addEventListener('hashchange',()=>{closeMenu();render({scroll:true,focus:true});});
render();if(!adult)$('#adult-dialog').showModal();
